<?php require_once "config/database.php";require_once "includes/functions.php";$pageTitle="Checkout";if(cart_count()<1)go("cart.php");$err="";$u=$_SESSION["user"]??[];if($_SERVER["REQUEST_METHOD"]==="POST"){$n=trim($_POST["name"]??"");$em=trim($_POST["email"]??"");$ad=trim($_POST["address"]??"");if(!$n||!filter_var($em,FILTER_VALIDATE_EMAIL)||!$ad)$err="Complete all fields.";else{try{$pdo->beginTransaction();if(isset($_SESSION["user"]["id"])){$uid=(int)$_SESSION["user"]["id"];$s=$pdo->prepare("UPDATE users SET name=?,email=?,address=? WHERE id=?");$s->execute([$n,$em,$ad,$uid]);}else{$s=$pdo->prepare("INSERT INTO users(name,email,password,role,address) VALUES(?,?,?,?,?)");$s->execute([$n,$em,password_hash(bin2hex(random_bytes(8)),PASSWORD_DEFAULT),"customer",$ad]);$uid=(int)$pdo->lastInsertId();}foreach($_SESSION["cart"] as $pid=>$q){$s=$pdo->prepare("SELECT price FROM products WHERE id=?");$s->execute([(int)$pid]);$p=$s->fetch();if($p){$s=$pdo->prepare("INSERT INTO orders(user_id,product_id,quantity,total_amount,status) VALUES(?,?,?,?,?)");$s->execute([$uid,(int)$pid,(int)$q,(float)$p["price"]*(int)$q,"Placed"]);}}$order=(int)$pdo->lastInsertId();$pdo->prepare("DELETE FROM cart_items WHERE user_id=?")->execute([$uid]);$pdo->commit();$_SESSION["cart"]=[];go("order_success.php?id=".$order);}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();$err="Could not place order.";}}}require "includes/header.php";?><section class="section"><div class="container formwrap"><div class="eyebrow">Secure Checkout</div><h1>Checkout</h1><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><form class="panel" method="post"><div class="group"><label>Name</label><input class="input" name="name" value="<?=e($u["name"]??"")?>" required></div><div class="group"><label>Email</label><input class="input" type="email" name="email" value="<?=e($u["email"]??"")?>" required></div><div class="group"><label>Address</label><textarea name="address" required><?=e($u["address"]??"")?></textarea></div><h3>Total: <span class="price">₹<?=number_format(cart_total($pdo),2)?></span></h3><button class="btn">Place Order</button></form></div></section><?php require "includes/footer.php";?>